const lines=[],groups={};const log=(...a)=>lines.push(a.join(' '));
function test(name,callback){if(CASE&&CASE!==name)return;let start=lines.length;try{callback()}catch(e){log(name,'ERROR',e.name,e.message)}groups[name]=lines.slice(start)}
function input(type,value){const i=document.createElement('input');i.type=type;i.value=value;return i}
const num=n=>Number.isNaN(n)?'NaN':String(n);
const iso=d=>d==null?null:Number.isNaN(d.getTime())?'invalid-date':d.toISOString();
test('numeric-api-types',()=>{for(const [type,value]of [['number','17'],['range','17'],['text','17'],['hidden','17'],['checkbox','17'],['date','2024-02-29'],['month','2024-02'],['week','2020-W53'],['time','12:34:56.120'],['datetime-local','2024-02-29T12:34']]){const i=input(type,value);log('numeric-api-types',type,num(i.valueAsNumber),i.valueAsDate?i.valueAsDate.toISOString():String(i.valueAsDate))}});
test('numeric-api-set',()=>{for(const value of [NaN,Infinity,-Infinity,-0,.5,'25',null,undefined,1n]){const i=input('number','17');let error='';try{i.valueAsNumber=value}catch(e){error=e.name}log('numeric-api-set',String(value),i.value,error)}});
test('numeric-api-inapplicable',()=>{for(const type of ['text','hidden','checkbox','color','file'])for(const value of [5,NaN,Infinity]){const i=input(type,'');let error='';try{i.valueAsNumber=value}catch(e){error=e.name}log('numeric-api-inapplicable',type,String(value),i.value,error)}});
test('numeric-api-brand',()=>{const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'valueAsNumber');let reads=0;const foreign={get value(){reads++;return '7'},set value(v){reads++}};for(const method of ['get','set']){try{if(method==='get')d.get.call(foreign);else d.set.call(foreign,8);log('numeric-api-brand',method,'accepted',reads)}catch(e){log('numeric-api-brand',method,e.name,reads)}}});
test('numeric-api-private',()=>{const i=input('number','17');let reads=0;Object.defineProperty(i,'value',{get(){reads++;return '999'},set(){reads++}});log('numeric-api-private','get',num(i.valueAsNumber),reads);i.valueAsNumber=23;const get=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').get;log('numeric-api-private','set',get.call(i),reads)});
test('numeric-api-date-values',()=>{for(const [type,values]of [['date',['0001-01-01','00001-01-01','2000-02-29','275760-09-13','275760-09-14']],['month',['0001-01','1969-12','2024-02']],['week',['0001-W01','1970-W01','2020-W53']],['time',['00:00','00:00:00.001','23:59:59.999']],['datetime-local',['0001-01-01T00:00','2024-02-29T12:34:56.123']]])for(const value of values){const i=input(type,value);log('numeric-api-date-values',JSON.stringify([type,value,num(i.valueAsNumber),iso(i.valueAsDate)]))}});
test('numeric-api-temporal-set',()=>{for(const type of ['date','month','week','time','datetime-local'])for(const value of [-1,-.5,0,.5,1,1.5,86400000,86400000.5,-86400000.5,1709210096123]){const i=input(type,'');let error='';try{i.valueAsNumber=value}catch(e){error=e.name}log('numeric-api-temporal-set',JSON.stringify([type,value,i.value,num(i.valueAsNumber),error]))}});
test('numeric-api-date-set',()=>{for(const type of ['date','month','week','time','datetime-local','number','text'])for(const value of [null,undefined,new Date('2024-02-29T23:59:56.123Z'),new Date(NaN),{},5]){const i=input(type,type==='number'?'17':'');let error='';try{i.valueAsDate=value}catch(e){error=e.name}log('numeric-api-date-set',JSON.stringify([type,value===undefined?'undefined':value instanceof Date?(Number.isNaN(value.getTime())?'invalid-date':value.toISOString()):value,i.value,error]))}});
test('numeric-api-range-nan',()=>{const i=input('range','10');i.valueAsNumber=NaN;log('numeric-api-range-nan',i.value,num(i.valueAsNumber));i.valueAsNumber=5.5;log('numeric-api-range-nan','step',i.value,num(i.valueAsNumber))});
test('numeric-api-date-private',()=>{const i=input('date','2024-02-29');let calls=0;Object.defineProperty(i,'value',{get(){calls++;return '2000-01-01'},set(){calls++}});const d=new Date('2025-03-01T01:02:03.004Z');Object.defineProperty(d,'getTime',{value(){calls++;throw Error('shadow')}});i.valueAsDate=d;const get=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').get;log('numeric-api-date-private',get.call(i),i.valueAsDate?.toISOString(),calls);const a=i.valueAsDate,b=i.valueAsDate;if(a){a.setUTCFullYear(2000);log('numeric-api-date-private','fresh',a===b,b.toISOString(),get.call(i))}});
test('numeric-api-number-coercion',()=>{const i=input('number','17');let calls=0;i.valueAsNumber={valueOf(){calls++;return 3}};log('numeric-api-number-coercion','once',calls,i.value);try{i.valueAsNumber={valueOf(){i.type='text';return 5}}}catch(e){log('numeric-api-number-coercion','change',i.type,i.value,e.name)}const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'valueAsNumber');try{d.set.call({}, {valueOf(){calls++;return 5}})}catch(e){log('numeric-api-number-coercion','brand-first',calls,e.name)}});
test('numeric-api-civil-cycle',()=>{const i=input('date','');for(let start=1;start<=400;start+=80){let mask='';for(let y=start;y<start+80;y++){let ok=true;for(const suffix of ['01-01','02-28','03-01','12-31']){const value=String(y).padStart(4,'0')+'-'+suffix;i.value=value;const d=new Date(0);d.setUTCFullYear(y,+suffix.slice(0,2)-1,+suffix.slice(3));const n=d.getTime();if(i.valueAsNumber!==n)ok=false;i.valueAsNumber=n;if(i.value!==value)ok=false}mask+=ok?'1':'0'}log('numeric-api-civil-cycle',start,mask)}});
test('numeric-api-week-cycle',()=>{const i=input('week','');for(let start=1;start<=400;start+=80){let mask='';for(let y=start;y<start+80;y++){const value=String(y).padStart(4,'0')+'-W01';i.value=value;const d=new Date(0);d.setUTCFullYear(y,0,4);const monday=d.getTime()-((d.getUTCDay()+6)%7)*86400000;let ok=i.valueAsNumber===monday;for(const day of [0,3,6]){i.valueAsNumber=monday+day*86400000;if(i.value!==value)ok=false}mask+=ok?'1':'0'}log('numeric-api-week-cycle',start,mask)}});
test('numeric-api-date-brand',()=>{const d=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'valueAsDate');let calls=0;for(const method of ['get','set']){try{if(method==='get')d.get.call({});else d.set.call({},{});log('numeric-api-date-brand',method,'accepted')}catch(e){log('numeric-api-date-brand',method,e.name)}}const i=input('date','2024-02-29');for(const value of [Object.create(Date.prototype),new Proxy(new Date(0),{get(){calls++;throw Error('proxy')}}),{[Symbol.toStringTag]:'Date',valueOf(){calls++;return 0}},()=>0]){let error='';try{i.valueAsDate=value}catch(e){error=e.name}log('numeric-api-date-brand',error,i.value,calls)}});
test('numeric-api-native-intrinsics',()=>{const i=input('date','2024-02-29'),m=input('month','2024-02'),w=input('week','2020-W53'),t=input('time','12:34:56.120'),n=input('number','17'),D=Date,N=Number,S=String,B=BigInt,sp=String.prototype,ex=RegExp.prototype.exec,sl=sp.slice,fl=Math.floor,ab=Math.abs,gt=Date.prototype.getTime;let calls=0;const poison=()=>{calls++;throw Error('author replacement')};let values;try{globalThis.Date=poison;globalThis.Number=poison;globalThis.String=poison;globalThis.BigInt=poison;RegExp.prototype.exec=poison;sp.slice=poison;Math.floor=poison;Math.abs=poison;i.valueAsNumber=1709210096123;m.valueAsNumber=649;w.valueAsNumber=1609113600000;t.valueAsNumber=45296120;n.valueAsNumber=23;values=[i.value,i.valueAsNumber,gt.call(i.valueAsDate),m.value,w.value,t.value,n.value,calls]}finally{globalThis.Date=D;globalThis.Number=N;globalThis.String=S;globalThis.BigInt=B;RegExp.prototype.exec=ex;sp.slice=sl;Math.floor=fl;Math.abs=ab}log('numeric-api-native-intrinsics',JSON.stringify(values))});
test('numeric-api-dirty-state',()=>{const n=document.createElement('input');n.type='number';n.defaultValue='17';try{n.valueAsNumber=Infinity}catch(e){log('numeric-api-dirty-state',e.name)}n.defaultValue='22';log('numeric-api-dirty-state','failed-number',n.value,n.defaultValue);n.valueAsNumber=NaN;n.defaultValue='23';log('numeric-api-dirty-state','cleared-number',n.value,n.defaultValue);const i=document.createElement('input');i.type='date';i.defaultValue='2024-02-29';try{i.valueAsDate={}}catch(e){log('numeric-api-dirty-state',e.name)}i.defaultValue='2025-03-01';log('numeric-api-dirty-state','failed-date',i.value,i.defaultValue);i.valueAsDate=new Date(NaN);i.defaultValue='2025-03-02';log('numeric-api-dirty-state','cleared-date',i.value,i.defaultValue)});
test('numeric-api-no-events',()=>{const f=document.createElement('form');document.body.append(f);let events=0;for(const type of ['number','date','month','week','time']){const i=document.createElement('input');i.type=type;i.name=type;f.append(i);for(const e of ['input','change'])i.addEventListener(e,()=>events++);if(type==='number')i.valueAsNumber=3;else i.valueAsDate=new Date('2024-02-29T12:34:56.123Z')}log('numeric-api-no-events',events,JSON.stringify([...new FormData(f)]));f.remove()});
// The model's valid positive calendar years are independent of Date TimeClip.
test('numeric-api-large-calendars',()=>{for(const type of ['date','month','week','datetime-local']){const i=input(type,'');i.valueAsNumber=Number.MAX_VALUE;log('numeric-api-large-calendars',type,i.value.length>0,i.valueAsNumber===Number.MAX_VALUE,type==='datetime-local'?i.valueAsDate===null:Number.isNaN(i.valueAsDate.getTime()))}const i=input('date','275760-09-14');log('numeric-api-large-calendars','date-boundary',i.valueAsNumber,Number.isNaN(i.valueAsDate.getTime()));i.valueAsNumber=i.valueAsNumber;log('numeric-api-large-calendars','roundtrip',i.value)});
